query BooksByTags($tagIds: [Int!], $limit: Int!) {
  taggable_counts(
    where: { tag_id: { _in: $tagIds }, taggable_type: { _eq: "Book" } }
    order_by: { count: desc }
    limit: $limit
  ) {
    count
    tag { tag }
    book {
      id
      title
      users_count
      contributions(limit: 1) { author { name } }
    }
  }
}

